DROP TABLE IF EXISTS `attendances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attendances` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint unsigned NOT NULL,
  `subject_assignment_id` bigint unsigned NOT NULL,
  `lesson_date` date NOT NULL,
  `lesson_number` tinyint unsigned NOT NULL,
  `status` enum('present','absent','excused','late','sick') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'present',
  `note` text COLLATE utf8mb4_unicode_ci,
  `marked_by` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendance_unique` (`student_id`,`subject_assignment_id`,`lesson_date`,`lesson_number`),
  KEY `attendances_marked_by_foreign` (`marked_by`),
  KEY `attendances_subject_assignment_id_lesson_date_index` (`subject_assignment_id`,`lesson_date`),
  KEY `attendances_student_id_status_index` (`student_id`,`status`),
  KEY `attendance_student_subject_date_idx` (`student_id`,`subject_assignment_id`,`lesson_date`),
  CONSTRAINT `attendances_marked_by_foreign` FOREIGN KEY (`marked_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attendances_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attendances_subject_assignment_id_foreign` FOREIGN KEY (`subject_assignment_id`) REFERENCES `subject_assignments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
