--
-- Table structure for table `category_scores`
--

DROP TABLE IF EXISTS `category_scores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `category_scores` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint unsigned NOT NULL,
  `subject_assignment_id` bigint unsigned NOT NULL,
  `semester_id` bigint unsigned NOT NULL,
  `lesson_date` date NOT NULL,
  `lesson_number` tinyint unsigned NOT NULL DEFAULT '1',
  `category` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `period` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'rating1',
  `score` decimal(5,2) NOT NULL,
  `max_score` decimal(5,2) NOT NULL,
  `graded_by` bigint unsigned NOT NULL,
  `is_locked` tinyint(1) NOT NULL DEFAULT '0',
  `locked_at` timestamp NULL DEFAULT NULL,
  `locked_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cat_scores_unique` (`student_id`,`subject_assignment_id`,`lesson_date`,`lesson_number`,`category`,`period`),
  KEY `category_scores_semester_id_foreign` (`semester_id`),
  KEY `category_scores_graded_by_foreign` (`graded_by`),
  KEY `cat_scores_main_idx` (`student_id`,`subject_assignment_id`,`semester_id`),
  KEY `cat_scores_lesson_idx` (`subject_assignment_id`,`lesson_date`,`lesson_number`),
  KEY `cs_student_assignment_semester_idx` (`student_id`,`subject_assignment_id`,`semester_id`),
  CONSTRAINT `category_scores_graded_by_foreign` FOREIGN KEY (`graded_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `category_scores_semester_id_foreign` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`) ON DELETE CASCADE,
  CONSTRAINT `category_scores_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `category_scores_subject_assignment_id_foreign` FOREIGN KEY (`subject_assignment_id`) REFERENCES `subject_assignments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1997 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

