--
-- Table structure for table `exams`
--

DROP TABLE IF EXISTS `exams`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exams` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subject_assignment_id` bigint unsigned NOT NULL,
  `semester_id` bigint unsigned NOT NULL,
  `teacher_id` bigint unsigned NOT NULL,
  `group_id` bigint unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `exam_type` enum('main','retake','retake_commission','rating1','rating2','midterm','quiz') COLLATE utf8mb4_unicode_ci NOT NULL,
  `format` enum('online_test','written','oral','mixed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'online_test',
  `duration_minutes` smallint unsigned NOT NULL DEFAULT '60',
  `total_questions_count` smallint unsigned NOT NULL DEFAULT '30',
  `simple_questions_count` smallint unsigned NOT NULL DEFAULT '20',
  `matching_questions_count` smallint unsigned NOT NULL DEFAULT '5',
  `passing_score` decimal(5,2) NOT NULL DEFAULT '50.00',
  `shuffle_questions` tinyint(1) NOT NULL DEFAULT '1',
  `shuffle_answers` tinyint(1) NOT NULL DEFAULT '1',
  `show_results_immediately` tinyint(1) NOT NULL DEFAULT '0',
  `allow_back_navigation` tinyint(1) NOT NULL DEFAULT '1',
  `max_attempts` tinyint unsigned NOT NULL DEFAULT '1',
  `auto_save` tinyint(1) NOT NULL DEFAULT '1',
  `starts_at` timestamp NULL DEFAULT NULL,
  `ends_at` timestamp NULL DEFAULT NULL,
  `status` enum('draft','scheduled','active','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `main_exam_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exams_semester_id_foreign` (`semester_id`),
  KEY `exams_subject_assignment_id_exam_type_index` (`subject_assignment_id`,`exam_type`),
  KEY `exams_group_id_semester_id_index` (`group_id`,`semester_id`),
  KEY `exams_status_starts_at_index` (`status`,`starts_at`),
  KEY `exams_teacher_id_index` (`teacher_id`),
  KEY `exams_main_exam_id_foreign` (`main_exam_id`),
  CONSTRAINT `exams_group_id_foreign` FOREIGN KEY (`group_id`) REFERENCES `groups` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exams_main_exam_id_foreign` FOREIGN KEY (`main_exam_id`) REFERENCES `exams` (`id`) ON DELETE SET NULL,
  CONSTRAINT `exams_semester_id_foreign` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exams_subject_assignment_id_foreign` FOREIGN KEY (`subject_assignment_id`) REFERENCES `subject_assignments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exams_teacher_id_foreign` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `exams`
--

