--
-- Table structure for table `retake_exam_attempts`
--

DROP TABLE IF EXISTS `retake_exam_attempts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `retake_exam_attempts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `retake_exam_id` bigint unsigned NOT NULL,
  `student_id` bigint unsigned NOT NULL,
  `retake_exam_student_id` bigint unsigned DEFAULT NULL,
  `attempt_number` tinyint unsigned NOT NULL DEFAULT '1',
  `started_at` timestamp NULL DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `auto_submitted_at` timestamp NULL DEFAULT NULL,
  `total_score` decimal(8,2) DEFAULT NULL,
  `max_possible_score` decimal(8,2) DEFAULT NULL,
  `percentage` decimal(6,2) DEFAULT NULL,
  `letter_grade` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `grade_point` decimal(3,2) DEFAULT NULL,
  `status` enum('in_progress','submitted','auto_submitted','graded') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress',
  `ip_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text COLLATE utf8mb4_unicode_ci,
  `disconnections` int unsigned NOT NULL DEFAULT '0',
  `last_activity_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rea_exam_student_attempt_unique` (`retake_exam_id`,`student_id`,`attempt_number`),
  KEY `retake_exam_attempts_student_id_foreign` (`student_id`),
  KEY `retake_exam_attempts_retake_exam_student_id_foreign` (`retake_exam_student_id`),
  KEY `rea_exam_student_attempt_idx` (`retake_exam_id`,`student_id`,`attempt_number`),
  CONSTRAINT `retake_exam_attempts_retake_exam_id_foreign` FOREIGN KEY (`retake_exam_id`) REFERENCES `retake_exams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `retake_exam_attempts_retake_exam_student_id_foreign` FOREIGN KEY (`retake_exam_student_id`) REFERENCES `retake_exam_students` (`id`) ON DELETE SET NULL,
  CONSTRAINT `retake_exam_attempts_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

