  PRIMARY KEY (`id`),
  UNIQUE KEY `res_unique` (`retake_exam_id`,`student_id`,`academic_debt_id`),
  KEY `retake_exam_students_examiner_id_foreign` (`examiner_id`),
  KEY `retake_exam_students_student_id_status_index` (`student_id`,`status`),
  KEY `retake_exam_students_academic_debt_id_index` (`academic_debt_id`),
