--
-- Table structure for table `subject_assignments`
--

DROP TABLE IF EXISTS `subject_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `subject_assignments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subject_id` bigint unsigned NOT NULL,
  `credits` tinyint unsigned DEFAULT NULL,
  `teacher_id` bigint unsigned NOT NULL,
  `group_id` bigint unsigned NOT NULL,
  `semester_id` bigint unsigned NOT NULL,
  `lesson_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'lecture',
  `hours_per_week` smallint unsigned NOT NULL DEFAULT '2',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `subject_assign_unique` (`subject_id`,`teacher_id`,`group_id`,`lesson_type`),
  KEY `subject_assignments_semester_id_foreign` (`semester_id`),
  KEY `subject_assignments_teacher_id_semester_id_index` (`teacher_id`,`semester_id`),
  KEY `subject_assignments_group_id_semester_id_index` (`group_id`,`semester_id`),
  KEY `sa_teacher_semester_active_idx` (`teacher_id`,`semester_id`,`is_active`),
  KEY `sa_group_semester_active_idx` (`group_id`,`semester_id`,`is_active`),
  KEY `subject_assignments_subject_id_semester_id_index` (`subject_id`,`semester_id`),
  CONSTRAINT `subject_assignments_group_id_foreign` FOREIGN KEY (`group_id`) REFERENCES `groups` (`id`) ON DELETE CASCADE,
  CONSTRAINT `subject_assignments_semester_id_foreign` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`) ON DELETE CASCADE,
  CONSTRAINT `subject_assignments_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `subject_assignments_teacher_id_foreign` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `subject_assignments`
