--
-- Table structure for table `vedomosts`
--

DROP TABLE IF EXISTS `vedomosts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vedomosts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subject_assignment_id` bigint unsigned NOT NULL,
  `group_id` bigint unsigned NOT NULL,
  `subject_id` bigint unsigned NOT NULL,
  `teacher_id` bigint unsigned DEFAULT NULL,
  `semester_id` bigint unsigned NOT NULL,
  `academic_year_id` bigint unsigned DEFAULT NULL,
  `number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exam_date` date DEFAULT NULL,
  `status` enum('draft','confirmed','printed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vedomosts_subject_assignment_id_semester_id_unique` (`subject_assignment_id`,`semester_id`),
  KEY `vedomosts_group_id_foreign` (`group_id`),
  KEY `vedomosts_subject_id_foreign` (`subject_id`),
  KEY `vedomosts_teacher_id_foreign` (`teacher_id`),
  KEY `vedomosts_semester_id_foreign` (`semester_id`),
  KEY `vedomosts_academic_year_id_foreign` (`academic_year_id`),
  CONSTRAINT `vedomosts_academic_year_id_foreign` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE SET NULL,
